provider "azurerm" {
  features {
    resource_group {
      prevent_deletion_if_contains_resources = false
    }
  }
}


## Section to provide a random Azure region for the resource group
# This allows us to randomize the region for the resource group.
module "regions" {
  source  = "Azure/avm-utl-regions/azurerm"
  version = "0.3.0"
}

# This allows us to randomize the region for the resource group.
resource "random_integer" "region_index" {
  max = length(module.regions.regions) - 1
  min = 0
}
## End of section to provide a random Azure region for the resource group

# This ensures we have unique CAF compliant names for our resources.
module "naming" {
  source  = "Azure/naming/azurerm"
  version = ">= 0.3.0"
}

# This is required for resource modules
resource "azurerm_resource_group" "this" {
  location = "East US 2" # Hardcoded instead of using module.regions because The "for_each" map includes keys derived from resource attributes that cannot be determined until apply, and so Terraform cannot determine the full set of keys that will identify the instances of this resource.
  name     = module.naming.resource_group.name_unique
}

# Datasource of current tenant ID
data "azurerm_client_config" "current" {}

# This is the module call
# Do not specify location here due to the randomization above.
# Leaving location as `null` will cause the module to use the resource group location
# with a data source.
module "test" {
  source = "Azure/avm-ptn-aks-production/azurerm"

  location = azurerm_resource_group.this.location
  name     = module.naming.kubernetes_cluster.name_unique
  network = {
    node_subnet_id = module.avm_res_network_virtualnetwork.subnets["subnet"].resource_id
    pod_cidr       = "192.168.0.0/16"
    service_cidr   = "10.2.0.0/16"
  }
  resource_group_name = azurerm_resource_group.this.name
  acr = {
    name                          = module.naming.container_registry.name_unique
    subnet_resource_id            = module.avm_res_network_virtualnetwork.subnets["private_link_subnet"].resource_id
    private_dns_zone_resource_ids = [azurerm_private_dns_zone.this.id]
  }
  enable_telemetry            = var.enable_telemetry # see variables.tf
  kubernetes_version          = "1.30"
  network_policy              = "calico"
  private_dns_zone_id         = azurerm_private_dns_zone.mydomain.id
  private_dns_zone_id_enabled = true
  rbac_aad_tenant_id          = data.azurerm_client_config.current.tenant_id
}

resource "azurerm_private_dns_zone" "this" {
  name                = "privatelink.azurecr.io"
  resource_group_name = azurerm_resource_group.this.name
}

resource "azurerm_private_dns_zone" "mydomain" {
  name                = "privatelink.eastus2.azmk8s.io"
  resource_group_name = azurerm_resource_group.this.name
}

module "avm_res_network_virtualnetwork" {
  source  = "Azure/avm-res-network-virtualnetwork/azurerm"
  version = "0.7.1"

  address_space       = ["10.31.0.0/16"]
  location            = azurerm_resource_group.this.location
  resource_group_name = azurerm_resource_group.this.name
  name                = "myvnet"
  subnets = {
    "subnet" = {
      name             = "nodecidr"
      address_prefixes = ["10.31.0.0/17"]
    }
    "private_link_subnet" = {
      name             = "private_link_subnet"
      address_prefixes = ["10.31.129.0/24"]
    }
  }
}

terraform {
  required_version = "~> 1.12"

  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 4.21"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.7"
    }
  }
}

provider "azurerm" {
  features {}
}

resource "random_string" "suffix" {
  length  = 4
  numeric = true
  special = false
  upper   = false
}

locals {
  common_tags = {
    created_by  = "terraform"
    project     = "Azure Landing Zones"
    owner       = "avm"
    environment = "demo"
  }
  resource_groups = {
    hub_primary = {
      name     = "rg-hub-primary-${random_string.suffix.result}"
      location = "swedencentral"
    }
  }
}

module "resource_groups" {
  source   = "Azure/avm-res-resources-resourcegroup/azurerm"
  version  = "0.2.0"
  for_each = local.resource_groups

  location         = each.value.location
  name             = each.value.name
  enable_telemetry = false
  tags             = local.common_tags
}

# This is the module call
module "test" {
  source = "Azure/avm-ptn-alz-connectivity-hub-and-spoke-vnet/azurerm"

  default_naming_convention = {
    virtual_network_name = "vnet-test-${random_string.suffix.result}-$${location}-$${sequence}"
  }
  enable_telemetry = false
  hub_and_spoke_networks_settings = {
    enabled_resources = {
      ddos_protection_plan = false
    }
  }
  hub_virtual_networks = {
    primary = {
      enabled_resources = {
        virtual_network_gateway_express_route = false
        virtual_network_gateway_vpn           = false
        bastion                               = false
        firewall                              = false
        private_dns_zones                     = false
      }
      location                  = local.resource_groups["hub_primary"].location
      default_hub_address_space = "192.168.0.0/16"
      default_parent_id         = module.resource_groups["hub_primary"].resource_id
    }
  }
  tags = local.common_tags
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 4.21"
    }
  }
}

provider "azurerm" {
  features {}
}

data "azurerm_client_config" "current" {}

locals {
  config_templating_inputs = {
    connectivity_resource_groups = var.connectivity_resource_groups
    virtual_wan_settings         = var.virtual_wan_settings
    virtual_wan_virtual_hubs     = var.virtual_wan_virtual_hubs
    management_group_settings    = var.management_group_settings
    management_resource_settings = var.management_resource_settings
    tags                         = var.tags
    connectivity_tags            = var.connectivity_tags
  }
}

module "config" {
  source = "github.com/Azure/alz-terraform-accelerator//templates/platform_landing_zone/modules/config-templating?ref=main"

  custom_replacements             = var.custom_replacements
  enable_telemetry                = var.enable_telemetry
  inputs                          = local.config_templating_inputs
  root_parent_management_group_id = ""
  starter_locations               = var.starter_locations
  subscription_id_connectivity    = data.azurerm_client_config.current.subscription_id
  subscription_id_identity        = data.azurerm_client_config.current.subscription_id
  subscription_id_management      = data.azurerm_client_config.current.subscription_id
  subscription_id_security        = data.azurerm_client_config.current.subscription_id
}

module "resource_groups" {
  source   = "Azure/avm-res-resources-resourcegroup/azurerm"
  version  = "0.2.0"
  for_each = module.config.outputs.connectivity_resource_groups

  location         = each.value.location
  name             = each.value.name
  enable_telemetry = false
  tags             = module.config.outputs.tags
}

# Build an implicit dependency on the resource groups
locals {
  resource_groups = {
    resource_groups = module.resource_groups
  }
  virtual_wan_settings     = merge(module.config.outputs.virtual_wan_settings, local.resource_groups)
  virtual_wan_virtual_hubs = (merge({ hubs = module.config.outputs.virtual_wan_virtual_hubs }, local.resource_groups)).hubs
}

# This is the module call
module "test" {
  source = "Azure/avm-ptn-alz-connectivity-virtual-wan/azurerm"

  enable_telemetry     = false
  tags                 = module.config.outputs.tags
  virtual_hubs         = local.virtual_wan_virtual_hubs
  virtual_wan_settings = local.virtual_wan_settings
}

resource "random_id" "id" {
  byte_length = 4
}

module "management" {
  source = "Azure/avm-ptn-alz-management/azurerm"

  automation_account_name      = "aa-terraform-${random_id.id.hex}"
  location                     = "eastus"
