    diagnostic_settings_queue = {
      queue1 = {
        name                  = "diag"
        workspace_resource_id = azurerm_log_analytics_workspace.example.id
        log_categories        = ["audit", "alllogs"]
        metric_categories     = ["Capacity", "Transaction"]
