provider "azurerm" {
  features {}
}
locals {
  test_regions = ["centralus", "westus", "eastus2"]
}
## Section to provide a random Azure region for the resource group
# This allows us to randomize the region for the resource group.
module "regions" {
  source  = "Azure/regions/azurerm"
  version = "0.3.0"
}

# This allows us to randomize the region for the resource group.
resource "random_integer" "region_index" {
  max = length(local.test_regions) - 1
  min = 0
}
## End of section to provide a random Azure region for the resource group

# This ensures we have unique CAF compliant names for our resources.
module "naming" {
  source  = "Azure/naming/azurerm"
  version = "0.3.0"
}

# This is required for resource modules
resource "azurerm_resource_group" "this" {
  location = "centralus" # module.regions.regions[random_integer.region_index.result].name
  name     = module.naming.resource_group.name_unique
}
resource "random_password" "admin_password" {
  length           = 16
  override_special = "!#$%&*()-_=+[]{}<>:?"
  special          = true
}

# This is the module call
# Do not specify location here due to the randomization above.
# Leaving location as `null` will cause the module to use the resource group location
# with a data source.
module "mysql_server" {
  source = "Azure/avm-res-dbformysql-flexibleserver/azurerm"

  location            = azurerm_resource_group.this.location
  name                = module.naming.mysql_server.name_unique
  resource_group_name = azurerm_resource_group.this.name
  administrator_login = "mysqladmin"
  # administrator_password = random_password.admin_password.result
  administrator_password_wo         = random_password.admin_password.result
  administrator_password_wo_version = 1 # increment to rotate password
  # source             = "Azure/avm-<res/ptn>-<name>/azurerm"
  # ...
  enable_telemetry = var.enable_telemetry # see variables.tf
  high_availability = {
    mode = "ZoneRedundant"
  }
  # Use the example variable so tflint sees it in use. Adjust the default in variables.tf to test other supported versions.
  mysql_version         = var.mysql_version
  public_network_access = var.public_network_access
  sku_name              = "GP_Standard_D2ds_v4"
  tags                  = null
}

